def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    mark = next(v for v in counts if v != bg and v != 2)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    cmin = min(c for r, c in pts)
    cmax = max(c for r, c in pts)
    bars = [r for r in range(h) if sum(v == mark for v in grid[r]) >= 4]
    out = [row[:] for row in grid]

    # Fill horizontal gaps; dense bars span the pattern's full width.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == mark]
        if len(cols) >= 4:
            lo, hi = cmin, cmax
        elif len(cols) >= 2:
            lo, hi = min(cols), max(cols)
        else:
            continue
        for c in range(lo, hi + 1):
            if out[r][c] == bg:
                out[r][c] = 2

    # Fill short gaps on well-supported vertical strokes. Dense horizontal
    # bars act as stroke intersections/endpoints across the full figure width.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == mark]
        if len(rows) < 4:
            continue
        if cmin <= c <= cmax:
            rows = sorted(set(rows + bars))
        for a, b in zip(rows, rows[1:]):
            if b - a <= 5:
                for r in range(a + 1, b):
                    if out[r][c] == bg:
                        out[r][c] = 2
    return out

